# Standard Schema support - T3 Env
created: undefined, last updated: 2026-06-13, [Read more](https://env.t3.gg/docs/standard-schema)

Standard Schema is a unified specification for TypeScript schema validation libraries.
It provides a common interface that allows different validation libraries to be interoperable.
This means that libraries like T3 Env can work with any validator that implements the Standard Schema interface.
...
export const env = createEnv({
server: {
DATABASE_URL: z.string().url(),
PORT: z.coerce.number().default(3000),
},
clientPrefix: "PUBLIC_",
client: {
PUBLIC_API_URL: z.string().url(),
},
runtimeEnv: process.env,
});
...
export const env = createEnv({
server: {
DATABASE_URL: v.pipe(v.string(), v.url()),
PORT: v.optional(v.pipe(v.string(), v.transform(Number)), "3000"),
},
...
client: {
PUBLIC_API_URL: v.pipe(v.string(), v.url()),
},
